@Test
void summarySidecarIsBoundedAndRebuildsFromCanonicalTail() throws IOException {
    var root = Files.createTempDirectory("ji-jsonl-summary-tail-");
    var repository = new JsonlSessionRepository(root);
    repository.create("session-1", new ModelRef("faux", "model"), "workspace", Instant.EPOCH);
    for (int revision = 0; revision < 200; revision++) {
        int value = revision;
        repository.update("session-1", revision,
                document -> document.setName(java.util.Optional.of("name-" + value + "-" + "x".repeat(1024))));
    }
    var source = root.resolve("session-1.jsonl");
    var sidecar = root.resolve("session-1.summary.json");
    long sourceBytes = Files.size(source);
    assertTrue(Files.size(sidecar) < sourceBytes / 100);

    Files.writeString(sidecar, "{broken", StandardOpenOption.TRUNCATE_EXISTING);
    var rebuilt = repository.listSummaries(SessionRepository.SummaryQuery.firstPage(java.util.Optional.empty()));
    assertEquals(200, rebuilt.sessions().getFirst().revision());
    assertTrue(Files.size(sidecar) < sourceBytes / 100);

    Files.delete(sidecar);
    assertEquals(200, repository.listSummaries(
            SessionRepository.SummaryQuery.firstPage(java.util.Optional.empty()))
            .sessions().getFirst().revision());
    assertTrue(Files.exists(sidecar));
}

@Test
void staleSummarySidecarIsRebuiltAfterCanonicalAppend() throws IOException {
    var root = Files.createTempDirectory("ji-jsonl-summary-stale-");
    var repository = new JsonlSessionRepository(root);
    repository.create("session-1", new ModelRef("faux", "model"), "workspace", Instant.EPOCH);
    var sidecar = root.resolve("session-1.summary.json");
    byte[] stale = Files.readAllBytes(sidecar);
    repository.update("session-1", 0, document -> document.setName(java.util.Optional.of("current")));
    Files.write(sidecar, stale, StandardOpenOption.TRUNCATE_EXISTING);

    var summary = repository.listSummaries(SessionRepository.SummaryQuery.firstPage(java.util.Optional.empty()))
            .sessions().getFirst();
    assertEquals(1, summary.revision());
    assertEquals("current", summary.name().orElseThrow());
}

